#include <grpcpp/grpcpp.h>
#include <jni.h>
#include <string>
#include <vector>
#include <mutex>
#include <memory>
#include "upload_service.grpc.pb.h"

static JavaVM* g_jvm = nullptr;
static std::mutex g_env_mutex;

class JNILocalFrameGuard {
public:
    JNILocalFrameGuard(JNIEnv* env, int capacity) : env_(env), pushed_(false) {
        if (env_->PushLocalFrame(capacity) == 0) {
            pushed_ = true;
        }
    }
    ~JNILocalFrameGuard() {
        if (pushed_) {
            env_->PopLocalFrame(nullptr);
        }
    }
    bool valid() const { return pushed_; }
private:
    JNIEnv* env_;
    bool pushed_;
};

struct ProcessingContext {
    std::string filename;
    std::vector<uint8_t> data;
    int32_t processing_flags;
    size_t max_output_size;
};

class NativeProcessor {
public:
    static NativeProcessor& instance() {
        static NativeProcessor inst;
        return inst;
    }

    bool validate_upload_metadata(const ProcessingContext& ctx) {
        if (ctx.filename.empty() || ctx.data.empty()) return false;
        if (ctx.filename.find("../") != std::string::npos) return false;
        if (ctx.data.size() > 10 * 1024 * 1024) return false;
        return true;
    }

    // Computes a safe buffer size for JNI array allocation
    // Uses the processing_flags to determine expansion factor
    jsize compute_jni_array_size(const ProcessingContext& ctx) {
        int expansion = 1;
        if (ctx.processing_flags & 0x01) expansion = 2;  // decompress
        if (ctx.processing_flags & 0x02) expansion = 4;  // decode + expand
        if (ctx.processing_flags & 0x04) expansion = 8;  // full transform

        size_t raw_size = ctx.data.size() * expansion;

        // Cap to max_output_size provided by caller
        size_t capped = std::min(raw_size, ctx.max_output_size);

        // Ensure we don't exceed INT32_MAX for jsize
        if (capped > static_cast<size_t>(std::numeric_limits<jsize>::max())) {
            capped = std::numeric_limits<jsize>::max();
        }

        return static_cast<jsize>(capped);
    }

    grpc::Status process_with_jni(const ProcessingContext& ctx, std::string* output) {
        JNIEnv* env = nullptr;
        bool did_attach = false;

        int rc = g_jvm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_8);
        if (rc == JNI_EDETACHED) {
            JavaVMAttachArgs args = { JNI_VERSION_1_8, nullptr, nullptr };
            if (g_jvm->AttachCurrentThread(reinterpret_cast<void**>(&env), &args) != 0) {
                return grpc::Status(grpc::INTERNAL, "JNI attach failed");
            }
            did_attach = true;
        } else if (rc != JNI_OK) {
            return grpc::Status(grpc::INTERNAL, "JNI GetEnv failed");
        }

        JNILocalFrameGuard frame(env, 32);
        if (!frame.valid()) {
            if (did_attach) g_jvm->DetachCurrentThread();
            return grpc::Status(grpc::INTERNAL, "JNI frame push failed");
        }

        jsize array_size = compute_jni_array_size(ctx);

        // Allocate the JNI byte array for processing
        jbyteArray j_input = env->NewByteArray(static_cast<jsize>(ctx.data.size()));
        jbyteArray j_output = env->NewByteArray(array_size);

        if (!j_input || !j_output) {
            if (did_attach) g_jvm->DetachCurrentThread();
            return grpc::Status(grpc::RESOURCE_EXHAUSTED, "JNI allocation failed");
        }

        // Copy input data into JNI array
        env->SetByteArrayRegion(j_input, 0, static_cast<jsize>(ctx.data.size()),
                                reinterpret_cast<const jbyte*>(ctx.data.data()));

        // Call Java processor
        jclass cls = env->FindClass("com/upload/FileProcessor");
        if (!cls) {
            if (did_attach) g_jvm->DetachCurrentThread();
            return grpc::Status(grpc::INTERNAL, "Java class not found");
        }

        jmethodID mid = env->GetStaticMethodID(cls, "transform", "([B[BI)I");
        if (!mid) {
            if (did_attach) g_jvm->DetachCurrentThread();
            return grpc::Status(grpc::INTERNAL, "Java method not found");
        }

        jint result_len = env->CallStaticIntMethod(cls, mid, j_input, j_output,
                                                    ctx.processing_flags);

        if (env->ExceptionCheck()) {
            env->ExceptionClear();
            if (did_attach) g_jvm->DetachCurrentThread();
            return grpc::Status(grpc::INTERNAL, "Java exception during processing");
        }

        // Extract result - use result_len returned by Java
        if (result_len > 0 && result_len <= array_size) {
            std::vector<jbyte> buf(result_len);
            env->GetByteArrayRegion(j_output, 0, result_len, buf.data());
            output->assign(reinterpret_cast<char*>(buf.data()), result_len);
        }

        if (did_attach) g_jvm->DetachCurrentThread();
        return grpc::Status::OK;
    }

private:
    NativeProcessor() = default;
};

class UploadServiceImpl final : public UploadService::Service {
public:
    grpc::Status ProcessUpload(grpc::ServerContext* context,
                               const UploadRequest* request,
                               UploadResponse* response) override {
        ProcessingContext ctx;
        ctx.filename = request->filename();
        ctx.data.assign(request->file_data().begin(), request->file_data().end());
        ctx.processing_flags = request->flags();
        ctx.max_output_size = request->max_output_size();

        auto& processor = NativeProcessor::instance();

        if (!processor.validate_upload_metadata(ctx)) {
            return grpc::Status(grpc::INVALID_ARGUMENT, "Invalid upload metadata");
        }

        std::string result;
        auto status = processor.process_with_jni(ctx, &result);
        if (status.ok()) {
            response->set_processed_data(result);
            response->set_success(true);
        }
        return status;
    }
};

void RunServer() {
    std::string server_address("0.0.0.0:50051");
    UploadServiceImpl service;

    grpc::ServerBuilder builder;
    builder.AddListeningPort(server_address, grpc::InsecureServerCredentials());
    builder.RegisterService(&service);
    builder.SetMaxReceiveMessageSize(16 * 1024 * 1024);

    std::unique_ptr<grpc::Server> server(builder.BuildAndStart());
    server->Wait();
}

JNIEXPORT jint JNICALL JNI_OnLoad(JavaVM* vm, void* reserved) {
    g_jvm = vm;
    return JNI_VERSION_1_8;
}
